---@param type IllustratedHandbookType
---@return table<number,IllustratedHandbookData>
function IllustratedHandbookDataManager:GetIllustratedHandbookDataList(type)
    local t = {}
    local dataTable = self.IllustratedHandbookDataDic[type]
    if type == IllustratedHandbookType.Portrait then
        ---@type table<string,IllustratedHandbookData>
        dataTable = {}
        for _, data in pairs(self.IllustratedHandbookDataDic[IllustratedHandbookType.Part]) do
            if dataTable[data.config.portraiticon] == nil or not dataTable[data.config.portraiticon]:IsActive() then
                dataTable[data.config.portraiticon] = data
            end
        end
    end
    local unActiveTable = {}
    for _, data in pairs(dataTable) do
        if data:IsActive() then
            table.insert(t, data)
        else
            table.insert(unActiveTable, data)
        end
    end
    if type == IllustratedHandbookType.Part or type == IllustratedHandbookType.Portrait then
        ---@param a IllustratedHandbookData
        ---@param b IllustratedHandbookData
        local sort = function(a, b)
            return a:GetCollectConfig().order < b:GetCollectConfig().order
        end
        table.sort(t, sort)
        table.sort(unActiveTable, sort)
    else
        ---@param a IllustratedHandbookData
        ---@param b IllustratedHandbookData
        local sort = function(a, b)
            return a:GetCupCollectConfig().C_ID < b:GetCollectConfig().C_ID
        end
        table.sort(t, sort)
        table.sort(unActiveTable, sort)
    end

    for i = 1, #unActiveTable do
        table.insert(t, unActiveTable[i])
    end
    return t
end

function IllustratedHandbookDataManager:CheckCupsNotLock(cups)
    local datatable= self.IllustratedHandbookDataDic[IllustratedHandbookType.Cup]
    local notLock = true
    if datatable[cups[1]] and not datatable[cups[1]]:IsActive() then
        notLock = false
    end
    if datatable[cups[2]] and not datatable[cups[2]]:IsActive() then
        notLock = false
    end
    if datatable[cups[3]] and not datatable[cups[3]]:IsActive() then
        notLock = false
    end
    return  notLock
end

